#include <iostream>#include <fstream>#include <string>using namespace std;int main() {    // Abrir ficheiro para leitura    ifstream arquivo("dados.txt");    string linha;    cout << "=== LEITOR DE FICHEIROS 📖 ===" << endl;    cout << endl;    // Verificar se abriu corretamente    if (arquivo.is_open()) {        cout << "Conteudo do ficheiro:" << endl;        cout << "----------------------" << endl;        // Ler linha por linha        while (getline(arquivo, linha)) {            cout << linha << endl;        }        // Fechar ficheiro        arquivo.close();        cout << endl;        cout << "Leitura concluida com sucesso 😄" << endl;    } else {        cout << "Erro ao abrir o ficheiro 😢" << endl;        cout << "Verifica se o ficheiro existe." << endl;    }    return 0;}